"use client";

import { MessageCircle } from "lucide-react";
import { trackEvent } from "@/lib/analytics";

interface WhatsAppButtonProps {
  phone?: string;
  message?: string;
}

export default function WhatsAppButton({
  phone = "40700000000",
  message = "Bună ziua, doresc o analiză gratuită pentru un credit.",
}: WhatsAppButtonProps) {
  const handleClick = () => {
    trackEvent("whatsapp_click", { destination_phone: phone });
    const encodedMsg = encodeURIComponent(message);
    const whatsappUrl = `https://wa.me/${phone}?text=${encodedMsg}`;
    window.open(whatsappUrl, "_blank", "noopener,noreferrer");
  };

  return (
    <button
      onClick={handleClick}
      className="whatsapp-float"
      aria-label="Contact pe WhatsApp"
      title="Discută pe WhatsApp"
    >
      <MessageCircle size={24} />
      <span className="wa-text">Discută pe WhatsApp</span>
    </button>
  );
}
